text:
{
  "title_novice": "Разрез фронта волновой дельты",
  "summary": [
    {"text": "Фронт волновой дельты записан в разрезе как ряд слоёв, где зерно укрупняется вверх.", "claims": ["c1"]},
    {"text": "Внизу может лежать тонкий слой от штормов, а выше — хорошо отсортированный песок с волновой рябью и косой слоистостью.", "claims": ["c2", "c3"]},
    {"text": "Биотурбация может нарушить первичные текстуры, а песчаники речных рукавов местами срезают разрез.", "claims": ["c4", "c5"]}
  ],
  "claims": [
    {"key": "c1", "text": "Фронт дельт выглядит как разрез, где зерно становится крупнее вверх; он похож на продвигающийся пляжевый фронт.", "kind": "observation", "unit_id": "u-040-901b96", "page": 40, "quote": "представлен разрезами с увеличением зернистости вверх, похожими на разрезы продвигающихся пляжевых фронтов.", "numbers": [], "question": null},
    {"key": "c2", "text": "В основании разреза фронта может быть тонкозернистый элемент с турбидитами, порождёнными штормами.", "kind": "observation", "unit_id": "u-040-901b96", "page": 40, "quote": "Тонкозернистый элемент в основании разреза фронта дельты может включать генерированные штормами турбидиты", "numbers": [], "question": null},
    {"key": "c3", "text": "В средней и верхней частях фронта преобладают хорошо отсортированные песчаники с выпуклой косой, волновой и параллельной слоистостью.", "kind": "observation", "unit_id": "u-040-901b96", "page": 40, "quote": "в средней и верхних частях разреза преобладают хорошо сортированные песчаники с выпуклой косой слоистостью, волновой слоистостью ряби, параллельной и косой слоистостью.", "numbers": [], "question": null},
    {"key": "c4", "text": "Биотурбация может быть заметной и сильно нарушать исходные текстуры слоёв.", "kind": "observation", "unit_id": "u-040-901b96", "page": 40, "quote": "Наблюдаемая биотурбация может быть весьма заметной и приводить к существенному нарушению первичных текстур.", "numbers": [], "question": null},
    {"key": "c5", "text": "Разрез фронта местами срезают песчаники речных дельтовых рукавов.", "kind": "observation", "unit_id": "u-040-901b96", "page": 40, "quote": "Разрезы эродированы песчаниками флювиальных дельтовых рукавов, по крайней мере, местами", "numbers": [], "question": null},
    {"key": "c6", "text": "Верхняя пляжевая фация может лучше развиться на флангах речных рукавов.", "kind": "observation", "unit_id": "u-040-901b96", "page": 40, "quote": "верхняя фация пляжа в составе фаций песчаников может лучше развиться на флангах этих рукавов", "numbers": [], "question": null},
    {"key": "c7", "text": "Автор считает, что пляжевые валы, вероятно, сосредоточены около рукавов, как в современных волновых дельтах.", "kind": "inference", "unit_id": "u-040-901b96", "page": 40, "quote": "что предполагает сосредоточение пляжевых валов около них, как в современных волновых дельтах.", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Разрез фронта похож на разрезы продвигающихся пляжевых фронтов: зерно становится крупнее кверху.", "claims": ["c1"], "hypothesis": false},
    {"text": "В основании может лежать тонкозернистый элемент, включающий штормовые турбидиты.", "claims": ["c2"], "hypothesis": false},
    {"text": "Выше в средней и верхней части преобладают хорошо сортированные песчаники: зёрна почти одного размера.", "claims": ["c3"], "hypothesis": false},
    {"text": "В этих песчаниках видны выпуклая косая, волновая рябь, параллельная и косая слоистость.", "claims": ["c3"], "hypothesis": false},
    {"text": "Объяснение добавлено (гипотеза): шторм поднимает осадок, и мутный поток ложится на дно.", "claims": [], "hypothesis": true},
    {"text": "Волны перебирают песок выше, поэтому зёрна становятся примерно одного размера (гипотеза).", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Проверяет, растёт ли зерно вверх по разрезу; это признак фронта волновой дельты.", "claims": ["c1"], "hypothesis": false},
    {"text": "В основании ищет тонкий слой, который может быть штормовым турбидитом.", "claims": ["c2"], "hypothesis": false},
    {"text": "В средней и верхней части ищет хорошо отсортированный песок с выпуклой косой слоистостью и рябью волн.", "claims": ["c3"], "hypothesis": false},
    {"text": "Оценивает, не нарушила ли биотурбация первичные текстуры (порядок проверки — гипотеза).", "claims": ["c4"], "hypothesis": true},
    {"text": "Ищет речные песчаники, срезающие разрез, и пляжевые песчаники на флангах этих рукавов (порядок проверки — гипотеза).", "claims": ["c5", "c6"], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Слово «может» показывает: тонкий слой и его состав не обязаны присутствовать в каждом разрезе.", "claims": ["c2"], "hypothesis": false},
    {"text": "Биотурбация может быть весьма заметной и затруднить чтение слоистости.", "claims": ["c4"], "hypothesis": false},
    {"text": "Речные песчаники срезают разрез только местами; из этого не следует, что весь песок речной.", "claims": ["c5"], "hypothesis": false},
    {"text": "Верхняя пляжевая фация может лучше развиться на флангах речных рукавов, а не везде.", "claims": ["c6"], "hypothesis": false},
    {"text": "Сходство с современными волновыми дельтами — аналогия, а не доказательство (гипотеза).", "claims": ["c7"], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Откуда берутся штормовые мутьевые потоки", "text": "Шторм взмучивает осадок; мутная вода стекает по склону и откладывает слой. Детали процесса — гипотеза, не из главы.", "claims": [], "hypothesis": true},
    {"title": "Почему волновой пляж сортирует песок", "text": "Волны перебирают песок, поэтому зёрна сортируются по размеру. Это общее объяснение, не из главы (гипотеза).", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Тонкозернистый элемент в основании: «может включать» штормовые турбидиты; присутствие не обязательно.", "claims": ["c2"]},
    {"text": "Биотурбация: «может быть весьма заметной» и «может приводить к существенному нарушению» текстур.", "claims": ["c4"]},
    {"text": "Размыв речными песчаниками: «по крайней мере, местами».", "claims": ["c5"]},
    {"text": "Пляжевая фация на флангах рукавов: «может лучше развиться».", "claims": ["c6"]}
  ],
  "terms_defined": [
    {"term": "штормовой турбидит", "term_en": "storm-generated turbidite", "abbr": "", "definition": "Слой, отложенный мутьевым потоком, который создал шторм. Мутьевой поток — вода с взвешенным осадком, быстро текущая по дну.", "claims": ["c2"]},
    {"term": "выпуклая косая слоистость", "term_en": "hummocky cross-stratification", "abbr": "", "definition": "Косые слои, которые в разрезе изгибаются выпукло, как купол. В тексте это признак средней и верхней части фронта.", "claims": ["c3"]},
    {"term": "сортированность", "term_en": "sorting", "abbr": "", "definition": "Насколько одинаковы зёрна по размеру. Хорошо сортированный песчаник — зёрна почти одного размера.", "claims": ["c3"]},
    {"term": "пляжевый фронт", "term_en": "beach face (shoreface)", "abbr": "", "definition": "Край пляжа у воды, который продвигается вперёд. Его разрезы похожи на разрезы фронта дельты.", "claims": ["c1"]},
    {"term": "параллельная слоистость", "term_en": "parallel lamination", "abbr": "", "definition": "Тонкие слои, лежащие ровно параллельно друг другу, без заметного наклона.", "claims": ["c3"]},
    {"term": "волновая слоистость ряби", "term_en": "wave ripple lamination", "abbr": "", "definition": "Слоистость, созданная волнами: мелкие волнистые гряды на поверхности песка, сохранённые в разрезе.", "claims": ["c3"]},
    {"term": "пляжевый вал", "term_en": "beach ridge", "abbr": "", "definition": "Песчаная гряда, которую волны насыпали вдоль берега.", "claims": ["c7"]}
  ],
  "terms_used": ["фронт дельты", "волновая дельта", "флювиальная дельта", "фация", "фациальная ассоциация фронта дельты", "укрупнение зерна вверх по разрезу", "продвижение (проградация) фронта", "турбидит", "биотурбация", "косая слоистость", "рябь", "песчаник", "алевролит", "аргиллит", "дельтовый рукав", "шторм", "пляжево-баровое побережье", "береговой вал", "поверхность размыва", "волновая переработка", "разрез", "мутьевой поток"],
  "formulas": [],
  "tables": [],
  "figures": [],
