  "misconception": {
    "pack_id": null,
    "wrong": "Любой песчаник в разрезе дельты — это речное русло.",
    "right": "Песчаники фронта волновой дельты бывают штормовыми и пляжевыми; речные песчаники лишь местами срезают разрез.",
    "claims": ["c2", "c3", "c5"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Профиль зернистости снизу вверх по керну или описанию разреза (источник — гипотеза).", "claims": [], "hypothesis": true},
      {"text": "Тип слоистости в каждом интервале: выпуклая косая, волновая рябь, параллельная, косая.", "claims": ["c3"], "hypothesis": false},
      {"text": "Степень биотурбации: насколько норы беспозвоночных нарушили первичные текстуры.", "claims": ["c4"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Интервал похож на фронт волновой дельты, если зерно растёт вверх и есть хорошо сортированный песок.", "claims": ["c1", "c3"], "hypothesis": false},
      {"text": "Внизу может быть штормовой слой, если тонкий элемент присутствует.", "claims": ["c2"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Тонкий слой внизу может отсутствовать: «может» не означает обязательность.", "claims": ["c2"], "hypothesis": false},
      {"text": "Биотурбация может нарушить первичные текстуры и затруднить чтение.", "claims": ["c4"], "hypothesis": false},
      {"text": "Речные песчаники местами срезают разрез и могут смешать признаки.", "claims": ["c5"], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Разрез как журнал с дозаписью: каждый новый слой пишется поверх старого, порядок слоёв показывает последовательность событий.",
    "breaks_where": "Журнал обычно не портится частично; слои могут быть стёрты биотурбацией или срезаны речным песком, и часть записи пропадает.",
    "hypothesis": true
  },
